def run_queue_ops(ops):
    in_stack = []
    out_stack = []
    output = []

    def move_if_needed():
        if not out_stack:
            while in_stack:
                out_stack.append(in_stack.pop())

    for op, arg in ops:
        if op == 'push':
            in_stack.append(arg)
        elif op == 'pop':
            move_if_needed()
            output.append(out_stack.pop())
        elif op == 'peek':
            move_if_needed()
            output.append(out_stack[-1])
        elif op == 'empty':
            output.append(len(in_stack) == 0 and len(out_stack) == 0)

    return output

